class _ScriptedClient:
    model = "test-model"
    temperature = 0.2

    def __init__(self, responses: list[LLMResponse]) -> None:
        self._responses = responses
        self.calls = 0
        self.call_records: list[dict[str, Any]] = []
        self._exhausted_final_repeats = 0

    def chat(
        self,
        *,
        messages: list[dict[str, Any]],
        tools: list[dict[str, Any]] | None = None,
        tool_choice: Any | None = None,
        stream: bool = False,
        on_text_delta=None,  # type: ignore[no-untyped-def]
        temperature: float | None = None,
    ) -> LLMResponse:
        _ = on_text_delta, temperature
        self.call_records.append(
            {
                "messages": list(messages),
                "tools": tools,
                "tool_choice": tool_choice,
                "stream": stream,
            }
        )
        if self.calls >= len(self._responses):
            if tools is not None:
                previous = self._responses[-1] if self._responses else None
                if (
                    previous is not None
                    and not previous.tool_calls
                    and str(previous.content or "").strip()
                    and self._exhausted_final_repeats < 1
                ):
                    self._exhausted_final_repeats += 1
                    self.calls += 1
                    return previous
                raise IndexError("scripted tool-enabled response exhausted")
            response = LLMResponse(
                content=(
                    "Completed work: partial progress was recorded.\n"
                    "Remaining work: completion-gate requirements are still unmet.\n"
                    "Known issues or risks: forced summary generated by test fallback."
                ),
                tool_calls=[],
                raw={},
            )
            self.calls += 1
            return response
        response = self._responses[self.calls]
        self.calls += 1
        return response


def _failed_edit_response() -> LLMResponse:
    """Observe mutation intent without changing files, before testing write safeguards.

    One-shot mode alone no longer authorizes implementation pressure. The missing
    target makes this real tool attempt fail without producing material changes.
    """
    return LLMResponse(
        content="",
        tool_calls=[
            ToolCall(
                id="attempt-initial-edit",
                name="fs_edit",
                arguments={
                    "path": "missing-edit-target.py",
                    "edits": [{"op": "replace_exact", "target": "before", "replacement": "after"}],
                },
            )
        ],
        raw={},
    )


def test_shell_run_semantic_progress_classifier_distinguishes_dumps_from_progress() -> None:
    for command in (
        "cat src/app.py",
        "grep -R TODO src",
        "ls -la",
        "head -40 README.md",
        "sed -n '1,80p' src/app.py",
        "python -c \"print('debug')\"",
    ):
        assert not _is_action_progress_tool(
            "shell_run",
            arguments={"cmd": command},
            result={"exit_code": 0, "stdout": "debug\n", "stderr": ""},
        )
        assert _is_exploration_only_tool(
            "shell_run",
            arguments={"cmd": command},
            result={"exit_code": 0, "stdout": "debug\n", "stderr": ""},
        )

    assert _is_action_progress_tool(
        "shell_run",
        arguments={"cmd": "python -m pytest tests/test_app.py -q"},
        result={"exit_code": 0, "stdout": "1 passed\n", "stderr": ""},
    )
    assert _is_action_progress_tool(
        "shell_run",
        arguments={"cmd": "cat > out.txt <<'EOF'\ndone\nEOF"},
        result={"exit_code": 0, "stdout": "", "stderr": ""},
        touched_paths={"out.txt"},
    )
    assert _is_action_progress_tool(
        "shell_run",
        arguments={"cmd": "python scripts/probe_target.py src/app.py"},
        result={"exit_code": 0, "stdout": "ok\n", "stderr": ""},
        focused=True,
    )
    assert not _is_action_progress_tool(
        "shell_run",
        arguments={"cmd": "python scripts/probe_target.py src/app.py"},
        result={"exit_code": 0, "stdout": "ok\n", "stderr": ""},
        focused=False,
    )
    assert _is_action_progress_tool("shell_background")
    assert _is_action_progress_tool("shell_service_start")
    assert _is_action_progress_tool("workspace_preview_start")
    assert _is_action_progress_tool("shell_service_status", result={"ready": True})
    assert _is_exploration_only_tool("shell_service_status", result={"ready": False})


def test_subagent_progress_uses_observed_child_effects_not_delegation_name() -> None:
    read_result = {
        "subagent": "explorer",
        "effects": ["delegate", "read_workspace"],
        "touched_repo_paths": [],
    }
    assert not _is_action_progress_tool("subagent_run", result=read_result)
    assert _is_exploration_only_tool("subagent_run", result=read_result)

    write_result = {
        "subagent": "implementer",
        "effects": ["delegate", "write_workspace"],
        "touched_repo_paths": ["src/app.py"],
    }
    assert _is_action_progress_tool("subagent_run", result=write_result)
    assert not _is_exploration_only_tool("subagent_run", result=write_result)


def test_background_subagent_progress_uses_workspace_semantics() -> None:
    assert not _is_action_progress_tool("subagent_status", arguments={"run_id": "all"})
    assert _is_exploration_only_tool("subagent_status", arguments={"run_id": "all"})

    assert not _is_action_progress_tool(
        "subagent_spawn",
        arguments={"name": "explorer", "task": "Map the code."},
    )
    assert _is_exploration_only_tool(
        "subagent_spawn",
        arguments={"name": "explorer", "task": "Map the code."},
    )
    assert _is_action_progress_tool(
        "subagent_spawn",
        arguments={
            "name": "implementer",
            "task": "Apply the change.",
            "workspace_view": "isolated",
        },
    )

    readonly_wait_result = {"results": {"run-a": {"effects": ["delegate", "read_workspace"]}}}
    assert not _is_action_progress_tool("subagent_wait", result=readonly_wait_result)
    assert _is_exploration_only_tool("subagent_wait", result=readonly_wait_result)

    write_wait_result = {
        "results": {
            "run-b": {
                "effects": ["delegate", "write_workspace"],
                "touched_repo_paths": ["src/app.py"],
            }
        }
    }
    assert _is_action_progress_tool("subagent_wait", result=write_wait_result)
    assert not _is_exploration_only_tool("subagent_wait", result=write_wait_result)


