class _ForcedToolChoiceScriptedClient(_ScriptedClient):
    supports_forced_tool_choice = True


class _RecordingSurface(NoopSurface):
    def __init__(self) -> None:
        super().__init__()
        self.errors: list[str] = []
        self.progress_updates: list[str] = []
        self.final_messages: list[str] = []

    def on_error(self, err: str) -> None:
        self.errors.append(err)

    def on_progress_update(self, message: str) -> None:
        self.progress_updates.append(message)

    def on_assistant_message_done(self, text: str) -> None:
        self.final_messages.append(text)


_VERIFY_OK_COMMAND = "pytest tests/test_cli.py -q"
_VERIFY_FAIL_COMMAND = "pytest tests/failing_case.py -q"
_VERIFY_IMPORT_ERROR_COMMAND = "pytest tests/search_notes_import_error.py -q"
_VERIFY_NAME_ERROR_COMMAND = "pytest tests/search_notes_name_error.py -q"
_VERIFY_RUFF_OK_COMMAND = "ruff check src/app.py"
_VERIFY_GO_OK_COMMAND = "go test ./pkg/..."
_VERIFY_GO_NO_TESTS_COMMAND = "go test -run NonExistent ./..."
_VERIFY_GO_NO_TEST_FILES_COMMAND = "go test ./..."
_VERIFY_GO_MIXED_OK_COMMAND = "go test ./mixed/..."


def _record_authoritative_verify_result(
    *,
    root: Path,
    state: TurnExecutionState,
    command: str = _VERIFY_OK_COMMAND,
    exit_code: int = 0,
) -> None:
    _record_tool_effect(
        root=root,
        state=state,
        tool_name="verify_run",
        arguments={"commands": [command]},
        status="ok",
        result={
            "commands": [command],
            "command_results": [
                {
                    "command": command,
                    "effective_command": command,
                    "ok": exit_code == 0,
                    "exit_code": exit_code,
                    "real_execution": True,
                    "output_preview": (
                        "" if exit_code == 0 else "AssertionError: authoritative check failed\n"
                    ),
                }
            ],
            "all_passed": exit_code == 0,
        },
        known_verification_commands=[command],
        verification_authoritative=True,
    )


def _record_supplemental_check(
    *,
    root: Path,
    state: TurnExecutionState,
    exit_code: int,
    known_command: str = _VERIFY_OK_COMMAND,
) -> None:
    _record_tool_effect(
        root=root,
        state=state,
        tool_name="shell_run",
        arguments={"cmd": "python checks.py"},
        status="ok",
        result={
            "cmd": "python checks.py",
            "effective_cmd": "python checks.py",
            "exit_code": exit_code,
            "stdout": "",
            "stderr": "AssertionError: task checker failed\n" if exit_code else "",
        },
        known_verification_commands=[known_command],
        verification_authoritative=True,
    )


def test_run_turn_deadline_smoke_resolves_route_intent_before_deadline_callbacks(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    cfg = AppConfig(model="test-model", routing_mode="auto", stream=False)
    _ = monkeypatch
    session = create_session(
        cfg=cfg,
        root=tmp_path,
        mode="fullaccess",
        yes=True,
        max_steps=2,
        no_log=False,
        api_key_override="override-key",
        one_shot_execution=True,
        session_log_dir_override=tmp_path / "sessions",
        session_id_override="deadline-smoke",
        subagents_enabled=True,
        execution_deadline=ExecutionDeadline.from_duration(120.0),
    )
    session.client = _ScriptedClient([LLMResponse(content="Done.", tool_calls=[], raw={})])  # type: ignore[assignment]

    try:
        exit_code = session.run_turn("Summarize the workspace.")
    except (NameError, UnboundLocalError) as exc:  # pragma: no cover - regression guard
        raise AssertionError("run_turn crashed before route intent resolution") from exc
    finally:
        session.close()

    assert exit_code == 0


def _fake_verify_command_result(command: str) -> VerifyCommandResult:
    normalized = " ".join(str(command).split())
    if normalized == _VERIFY_OK_COMMAND:
        return VerifyCommandResult(
            command=command,
            exit_code=0,
            output="ok\n",
            real_execution=True,
        )
    if normalized == _VERIFY_FAIL_COMMAND:
        return VerifyCommandResult(
            command=command,
            exit_code=1,
            output="FAILED tests/failing_case.py::test_failure - AssertionError\n",
        )
    if normalized == _VERIFY_IMPORT_ERROR_COMMAND:
        return VerifyCommandResult(
            command=command,
            exit_code=1,
            output="ImportError: cannot import name search_notes\n",
        )
    if normalized == _VERIFY_NAME_ERROR_COMMAND:
        return VerifyCommandResult(
            command=command,
            exit_code=1,
            output="NameError: search_notes is not defined\n",
        )
    if normalized == _VERIFY_RUFF_OK_COMMAND:
        return VerifyCommandResult(
            command=command,
            exit_code=0,
            output="All checks passed!\n",
            real_execution=True,
        )
    if normalized == _VERIFY_GO_OK_COMMAND:
        return VerifyCommandResult(
            command=command,
            exit_code=0,
            output="ok\texample/pkg\t0.002s\n",
            real_execution=True,
        )
    if normalized == _VERIFY_GO_NO_TESTS_COMMAND:
        return VerifyCommandResult(
            command=command,
            exit_code=0,
            output="ok\texample/pkg\t0.002s [no tests to run]\n",
            real_execution=False,
            non_execution_reason="go_test_no_tests_to_run",
        )
    if normalized == _VERIFY_GO_NO_TEST_FILES_COMMAND:
        return VerifyCommandResult(
            command=command,
            exit_code=0,
            output="?   \texample/pkg\t[no test files]\n",
            real_execution=False,
            non_execution_reason="go_test_no_test_files",
        )
    if normalized == _VERIFY_GO_MIXED_OK_COMMAND:
        return VerifyCommandResult(
            command=command,
            exit_code=0,
            output="?   \texample/pkg1\t[no test files]\nok  \texample/pkg2\t0.002s\n",
            real_execution=True,
        )
    return VerifyCommandResult(
        command=command,
        exit_code=1,
        output=f"unexpected verify command in test: {command}\n",
    )


def test_verification_failure_snippet_prefers_structured_primary_failure() -> None:
    snippet = agent_loop_mod.extract_verification_failure_snippet(
        tool_name="verify_run",
        result={
            "summary": "verification failed (0/1); failed: pytest tests/search_notes_name_error.py -q",
            "failed_commands": ["pytest tests/search_notes_name_error.py -q"],
            "primary_failure": {
                "command": "pytest tests/search_notes_name_error.py -q",
                "effective_command": "pytest tests/search_notes_name_error.py -q",
                "snippet": "NameError: search_notes is not defined",
                "output_truncated": False,
                "fallback_used": False,
            },
            "command_results": [
                {
                    "command": "pytest tests/search_notes_name_error.py -q",
                    "effective_command": "pytest tests/search_notes_name_error.py -q",
                    "exit_code": 1,
                    "ok": False,
                    "output_preview": "verification failed\n",
                }
            ],
        },
    )

    assert snippet == "NameError: search_notes is not defined"


def test_no_material_completion_gate_nudge_is_action_first() -> None:
    message = _completion_gate_nudge_message(
        ["no_material_edits", "verification_not_attempted"],
    )

    assert message.startswith("Finalization check - one pass before you finish:")
    assert "No file changes are recorded yet" in message
    assert "Expected verification has not been completed" in message
    assert "this checklist is advisory" in message


def test_verification_not_attempted_completion_gate_nudge_stays_verification_specific() -> None:
    message = _completion_gate_nudge_message(
        ["verification_not_attempted"],
        missing_verification_commands=["pytest -q"],
    )

    assert "Expected verification not yet run: pytest -q" in message
    assert "Run them, or state why they don't apply" in message
    assert "No file changes are recorded yet" not in message


def test_verification_failed_completion_gate_nudge_instructs_fix_then_rerun() -> None:
    message = _completion_gate_nudge_message(
        ["verification_failed"],
        verification_failure_snippet="pytest failed\nNameError: search_notes is not defined",
    )

    assert (
        "An unresolved verification failure is recorded: NameError: search_notes is not defined"
        in message
    )
    assert "Fix and re-run" in message
    assert "Re-read the task statement once" in message


def _latest_completion_gate_payload(
    sessions_dir: Path,
    session_id: str,
) -> dict[str, Any]:
    events = list(read_session_events(sessions_dir / f"{session_id}.jsonl"))
    return _latest_completion_gate_acceptance_payload(events)


def _latest_completion_gate_acceptance_payload(events: list[dict[str, Any]]) -> dict[str, Any]:
    accepted_events = [
        event
        for event in events
        if event.get("type") == "completion_gate_accepted_with_open_problems"
    ]
    assert accepted_events
    return dict(accepted_events[-1].get("payload") or {})


def _assert_no_completion_gate_terminal_events(events: list[dict[str, Any]]) -> None:
    assert not any(
        event.get("type")
        in {
            "one_shot_completion_gate_incomplete_after_retries",
            "one_shot_no_material_edits_incomplete_after_retries",
            "completion_gate_terminal_failure",
        }
        for event in events
    )


def _assert_forced_final_summary_emitted(events: list[dict[str, Any]]) -> str:
    assert any(event.get("type") == "forced_final_summary_requested" for event in events)
    summary_events = [
        event
        for event in events
        if event.get("type") in {"forced_final_summary_completed", "forced_final_summary_fallback"}
    ]
    assert summary_events
    assistant_events = [event for event in events if event.get("type") == "assistant_message"]
    final_events = [event for event in events if event.get("type") == "final"]
    assert assistant_events
    assert final_events
    content = str((assistant_events[-1].get("payload") or {}).get("content") or "")
    assert content
    final_payload = dict(final_events[-1].get("payload") or {})
    summary_payload = dict(summary_events[-1].get("payload") or {})
    assert str(final_payload.get("content") or "") == content
    assert final_payload["controller_interventions_total"] >= 1
    assert (
        final_payload["controller_interventions_total"]
        == summary_payload["controller_interventions_total"]
    )
    assert "controller_interventions" in final_payload
    return content


def _assert_last_forced_summary_request(
    client: _ScriptedClient,
    *,
    latest_assistant_text: str,
    termination_cause: str,
) -> None:
    assert client.call_records
    request = client.call_records[-1]
    assert request["tools"] is None
    request_messages = request["messages"]
    assert request_messages[-2] == {
        "role": "assistant",
        "content": latest_assistant_text,
    }
    assert str(request_messages[-1].get("role")) == "system"
    assert f"Stop reason: {termination_cause}" in str(request_messages[-1].get("content"))


def test_completion_gate_remembers_failed_configured_command_after_subset_pass(
    tmp_path: Path,
) -> None:
    commands = ["go test ./...", "go run ./cmd/importer fixtures/mixed.csv"]
    state = TurnExecutionState(
        execution_requested=True,
        expected_verification_commands=set(commands),
        material_edit_count=1,
        touched_repo_paths={"cmd/importer/main.go"},
    )

    _record_tool_effect(
        root=tmp_path,
        state=state,
        tool_name="verify_run",
        arguments={"commands": commands},
        status="ok",
        result={
            "commands": commands,
            "command_results": [
                {
                    "command": "go test ./...",
                    "effective_command": "go test ./...",
                    "ok": True,
                    "exit_code": 0,
                    "real_execution": True,
                    "output_preview": "ok\texample/importer\t0.003s\n",
                },
                {
                    "command": "go run ./cmd/importer fixtures/mixed.csv",
                    "effective_command": "go run ./cmd/importer fixtures/mixed.csv",
                    "ok": False,
                    "exit_code": 1,
                    "real_execution": None,
                    "output_preview": "exit status 1\n",
                },
            ],
        },
        known_verification_commands=commands,
    )
    assert state.failed_verification_commands() == {"go run ./cmd/importer fixtures/mixed.csv"}

    _record_tool_effect(
        root=tmp_path,
        state=state,
        tool_name="verify_run",
        arguments={"commands": ["go test ./..."]},
        status="ok",
        result={
            "commands": ["go test ./..."],
            "command_results": [
                {
                    "command": "go test ./...",
                    "effective_command": "go test ./...",
                    "ok": True,
                    "exit_code": 0,
                    "real_execution": True,
                    "output_preview": "ok\texample/importer\t(cached)\n",
                }
            ],
            "all_passed": True,
        },
        known_verification_commands=commands,
    )

    assert state.covered_verification_commands == {"go test ./..."}
    assert state.failed_verification_commands() == {"go run ./cmd/importer fixtures/mixed.csv"}
    assert "go run ./cmd/importer fixtures/mixed.csv" in state.first_failed_verification_snippet()
    problems = _completion_gate_problems(
        state=state,
        final_text="Implemented and verified.",
        blocked=False,
        verification_expected=True,
        require_material_edit_evidence=False,
    )
    assert "verification_failed" in problems
    assert "verification_incomplete" not in problems


