def test_shell_service_start_counts_as_material_work_and_durable_acceptance(
    tmp_path: Path,
) -> None:
    contract = build_acceptance_contract(
        root=tmp_path,
        instruction="Keep the service running on port 8080.",
    )
    state = TurnExecutionState(
        execution_requested=True,
        acceptance_contract=contract,
    )
    payload = {
        "service_id": "svc_ready",
        "ownership": "DURABLE_SERVICE",
        "status": "running",
        "alive": True,
        "identity_valid": True,
        "readiness": {
            "type": "tcp",
            "status": "ready",
            "port": 8080,
            "endpoint_owned": True,
            "strength": "owned_endpoint",
        },
    }

    _record_tool_effect(
        root=tmp_path,
        state=state,
        tool_name="shell_service_start",
        arguments={"cmd": "python -m http.server 8080"},
        status="ok",
        result=payload,
        known_verification_commands=[],
    )
    finalize_acceptance_contract(
        contract=contract,
        root=tmp_path,
        touched_paths=set(),
        durable_service_status=lambda _service_id: payload,
    )

    criteria = [
        criterion
        for criterion in contract.criteria
        if criterion.kind == AcceptanceCriterionKind.PERSISTENT_SERVICE
    ]
    assert state.material_edit_count == 1
    assert state.material_edit_tools == {"shell_service_start"}
    assert criteria[0].status == AcceptanceCriterionStatus.PASSED
    assert state.failed_verification_commands() == set()
    problems = _completion_gate_problems(
        state=state,
        final_text="Implemented and verified.",
        blocked=False,
        verification_expected=True,
        require_material_edit_evidence=False,
    )
    assert "no_material_edits" not in problems
    assert "acceptance_criteria_unverified" not in problems


