def test_provider_declared_final_after_failed_service_tool_avoids_model_control(
    tmp_path: Path,
) -> None:
    cfg = AppConfig(model="test-model", routing_mode="code_only")
    sessions_dir = tmp_path / "sessions"
    session = create_session(
        cfg=cfg,
        root=tmp_path,
        mode="auto",
        yes=True,
        max_steps=6,
        no_log=False,
        api_key_override="override-key",
        one_shot_execution=False,
        verification_enabled=False,
        session_log_dir_override=sessions_dir,
        session_id_override="structured-final-after-service-failure",
    )
    session.tools["shell_service_start"] = ToolDef(
        name="shell_service_start",
        description="Start a durable local service.",
        parameters={"type": "object", "properties": {}},
        run=lambda _args: {"error": "Durable service tools are unavailable in this session."},
    )
    session.tool_list = [tool.as_openai_tool() for tool in session.tools.values()]
    final_text = (
        "I couldn't expose the Next.js site because the service runtime is unavailable. "
        "Run npm run dev locally, then open http://localhost:3000."
    )
    session.client = _ScriptedClient(
        [
            LLMResponse(
                content="Starting the Next.js development server.",
                tool_calls=[
                    ToolCall(
                        id="tc-service",
                        name="shell_service_start",
                        arguments={"cmd": "npm run dev"},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content=final_text,
                tool_calls=[],
                raw={},
                assistant_phase=AssistantResponsePhase.FINAL_ANSWER,
            ),
        ]
    )  # type: ignore[assignment]

    try:
        exit_code = session.run_turn("Host the website locally now.")
    finally:
        session.close()

    assert exit_code == 0
    assert session.client.calls == 2  # type: ignore[attr-defined]
    events = list(
        read_session_events(sessions_dir / "structured-final-after-service-failure.jsonl")
    )
    event_types = [event.get("type") for event in events]
    assert "tool_result" in event_types
    assert "interactive_non_final_progress_detected" not in event_types
    assert "continuation_nudge" not in event_types
    assert "completion_gate_nudge" not in event_types
    assert "empty_model_response_model_control_anomaly" not in event_types
    assert "empty_model_response_anomaly_incomplete_after_retries" not in event_types
    final_events = [event for event in events if event.get("type") == "final"]
    assert final_events[-1]["payload"]["content"] == final_text


def test_one_shot_plan_only_then_final_records_single_continuation_intervention(
    tmp_path: Path,
) -> None:
    cfg = AppConfig(model="test-model", routing_mode="code_only")
    sessions_dir = tmp_path / "sessions"
    session = create_session(
        cfg=cfg,
        root=tmp_path,
        mode="auto",
        yes=True,
        max_steps=10,
        no_log=False,
        api_key_override="override-key",
        one_shot_execution=True,
        session_log_dir_override=sessions_dir,
        session_id_override="one-shot-plan-then-final-interventions",
    )
    session.client = _ScriptedClient(
        [
            LLMResponse(
                content="I will inspect the repo, make the edit, and then verify it.",
                tool_calls=[],
                raw={},
                assistant_phase=AssistantResponsePhase.COMMENTARY,
            ),
            LLMResponse(
                content="I have enough information to finish this turn.",
                tool_calls=[],
                raw={},
            ),
        ]
    )  # type: ignore[assignment]
    try:
        exit_code = session.run_turn("Implement search command and update tests.")
    finally:
        session.close()

    assert exit_code == 0
    events = list(
        read_session_events(sessions_dir / "one-shot-plan-then-final-interventions.jsonl")
    )
    interventions = [
        dict(event.get("payload") or {})
        for event in events
        if event.get("type") == "controller_intervention"
    ]
    headline_interventions = [
        payload for payload in interventions if payload.get("headline_counted") is True
    ]
    assert [payload["detail"] for payload in headline_interventions] == [
        "non_final_progress_continuation_nudge",
    ]
    assert [payload["class"] for payload in headline_interventions] == [
        "continuation",
    ]
    finalized = [
        dict(event.get("payload") or {})
        for event in events
        if event.get("type") == "turn_intent_finalized"
    ]
    assert finalized
    assert finalized[-1]["controller_interventions_total"] == 1
    assert finalized[-1]["controller_interventions"]["by_class"] == {
        # Request artifact interpretation and reproduction guidance are context
        # setup; only the actual continuation counts as a corrective intervention.
        "context_setup": 2,
        "continuation": 1,
    }


