@pytest.mark.parametrize(
    ("instruction", "session_id"),
    [
        ("Implement search command.", "one-shot-repeat-progress"),
        ("Make a worthwhile improvement in Flask.", "one-shot-repeat-progress-flask"),
    ],
)
def test_one_shot_non_final_progress_accepts_second_final_after_single_nudge(
    tmp_path: Path,
    instruction: str,
    session_id: str,
) -> None:
    cfg = AppConfig(model="test-model", routing_mode="code_only")
    sessions_dir = tmp_path / "sessions"
    surface = _RecordingSurface()
    session = create_session(
        cfg=cfg,
        root=tmp_path,
        mode="auto",
        yes=True,
        max_steps=7,
        no_log=False,
        api_key_override="override-key",
        one_shot_execution=True,
        session_log_dir_override=sessions_dir,
        session_id_override=session_id,
        surface=surface,
    )
    repeated_progress_text = "I will implement search next."
    client = _ScriptedClient(
        [
            _failed_edit_response(),
            LLMResponse(
                content=repeated_progress_text,
                tool_calls=[],
                raw={},
                assistant_phase=AssistantResponsePhase.COMMENTARY,
            ),
            LLMResponse(
                content=repeated_progress_text,
                tool_calls=[],
                raw={},
                assistant_phase=AssistantResponsePhase.COMMENTARY,
            ),
            LLMResponse(
                content=repeated_progress_text,
                tool_calls=[],
                raw={},
                assistant_phase=AssistantResponsePhase.COMMENTARY,
            ),
            LLMResponse(
                content=(
                    "Completed work: identified the requested implementation step.\n"
                    "Remaining work: the change is still incomplete.\n"
                    "Known issues or risks: repeated non-final progress stopped the run."
                ),
                tool_calls=[],
                raw={},
            ),
        ]
    )
    session.client = client  # type: ignore[assignment]

    try:
        exit_code = session.run_turn(instruction)
    finally:
        session.close()

    assert exit_code == 0
    assert client.calls == 3  # Failed edit, progress, and one bounded continuation.

    events = list(read_session_events(sessions_dir / f"{session_id}.jsonl"))
    assert any(event.get("type") == "continuation_nudge" for event in events)
    assert any(
        event.get("type") == "completion_gate_accepted_with_open_problems" for event in events
    )
    assert not [
        event for event in events if event.get("type") == "one_shot_incomplete_after_retries"
    ]
    assert not [event for event in events if event.get("type") == "forced_final_summary_requested"]
    assert surface.errors == []
    # Turn-contract v2: a zero-edit execute turn now finalizes with a visible
    # advisory-completion suffix (apply-don't-advise). The model text is preserved.
    assert surface.final_messages[-1].startswith(repeated_progress_text)
    assert "No files were changed" in surface.final_messages[-1]


