@pytest.mark.parametrize("one_shot_execution", [False, True])
def test_one_shot_empty_git_diff_finalization_is_blocked_until_a_change_exists(
    tmp_path: Path,
    one_shot_execution: bool,
) -> None:
    repo = tmp_path / "repo"
    _init_git_repo_with_commit(repo)
    _commit_repo_file(repo, "src/app.py", "VALUE = 'old'\n")
    sessions_dir = tmp_path / "sessions"
    session_id = "one-shot-empty-diff-blocked"
    session = create_session(
        cfg=AppConfig(model="test-model", routing_mode="code_only"),
        root=repo,
        mode="auto",
        yes=True,
        max_steps=7,
        no_log=False,
        api_key_override="override-key",
        one_shot_execution=one_shot_execution,
        enable_chat_turn_step_budget=True,
        verification_enabled=False,
        session_log_dir_override=sessions_dir,
        session_id_override=session_id,
    )
    client = _ScriptedClient(
        [
            _failed_edit_response(),
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc-read",
                        name="fs_read",
                        arguments={"path": "src/app.py"},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content="The correct fix would be to change src/app.py.",
                tool_calls=[],
                raw={},
            ),
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc-write",
                        name="fs_write",
                        arguments={"path": "src/app.py", "content": "VALUE = 'fixed'\n"},
                    )
                ],
                raw={},
            ),
            LLMResponse(content="Updated src/app.py.", tool_calls=[], raw={}),
            LLMResponse(content="Updated src/app.py.", tool_calls=[], raw={}),
        ]
    )
    session.client = client  # type: ignore[assignment]

    try:
        exit_code = session.run_turn("Fix the bug in src/app.py.")
    finally:
        session.close()

    events = list(read_session_events(sessions_dir / f"{session_id}.jsonl"))
    blocked = [event for event in events if event.get("type") == "empty_diff_finalization_blocked"]
    assert exit_code == 0
    assert blocked
    assert not any(event.get("type") == "empty_diff_forced" for event in events)
    corrective = str((blocked[-1].get("payload") or {}).get("message") or "")
    assert "An implementation attempt was observed" in corrective
    assert "no file changes are present" in corrective
    assert "Check the attempted operation and its result" in corrective
    assert "Complete the requested change and verify it" in corrective
    assert (
        "src/app.py"
        in subprocess.run(
            ["git", "-C", os.fspath(repo), "diff", "--name-only"],
            check=True,
            capture_output=True,
            text=True,
        ).stdout.splitlines()
    )


