def test_one_shot_blocker_prose_does_not_bypass_code_verification_failure(
    tmp_path: Path,
) -> None:
    # A model-authored blocker convention does not override a genuine code-verification
    # failure caused by its own edit. Prose is never promoted to structural blocker state.
    cfg = AppConfig(
        model="test-model",
        routing_mode="code_only",
        verify_commands=[_VERIFY_FAIL_COMMAND],
    )
    sessions_dir = tmp_path / "sessions"
    session = create_session(
        cfg=cfg,
        root=tmp_path,
        mode="auto",
        yes=True,
        max_steps=8,
        no_log=False,
        api_key_override="override-key",
        one_shot_execution=True,
        session_log_dir_override=sessions_dir,
        session_id_override="one-shot-code-failure-not-blocker",
    )
    session.client = _ScriptedClient(
        [
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc1",
                        name="fs_write",
                        arguments={"path": "src/app.py", "content": "print('changed')\n"},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc2",
                        name="verify_run",
                        arguments={"commands": [_VERIFY_FAIL_COMMAND]},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content=(
                    "blocked: verification keeps failing after my change. category: environment"
                ),
                tool_calls=[],
                raw={},
            ),
            LLMResponse(
                content=(
                    "blocked: verification keeps failing after my change. category: environment"
                ),
                tool_calls=[],
                raw={},
            ),
            LLMResponse(
                content=(
                    "blocked: verification keeps failing after my change. category: environment"
                ),
                tool_calls=[],
                raw={},
            ),
            LLMResponse(
                content=(
                    "Completed work: implementation was attempted.\n"
                    "Remaining work: verification is still failing.\n"
                    "Known issues or risks: blocker text did not override failing verification."
                ),
                tool_calls=[],
                raw={},
            ),
        ]
    )  # type: ignore[assignment]

    try:
        exit_code = session.run_turn("Implement the requested code change.")
    finally:
        session.close()

    assert exit_code == 0
    events = list(read_session_events(sessions_dir / "one-shot-code-failure-not-blocker.jsonl"))
    failed_events = [
        event for event in events if event.get("type") == "one_shot_completion_gate_failed"
    ]
    assert failed_events
    payload = dict(failed_events[-1].get("payload") or {})
    assert payload.get("blocked_response") is False
    assert payload.get("blocked_response_allows_completion") is False
    assert "verification_failed" in set(payload.get("problems") or [])
    accepted_payload = _latest_completion_gate_acceptance_payload(events)
    assert "verification_failed" in set(accepted_payload.get("problems") or [])


def test_one_shot_infra_verification_blocker_can_finalize(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    def fake_run_task_verification(
        *,
        root: Path,
        commands: list[str],
        artifact_path: Path,
        cfg: AppConfig,
    ) -> VerifyRunResult:
        _ = root, cfg
        artifact_path.parent.mkdir(parents=True, exist_ok=True)
        artifact_path.write_text(
            "$ ./gradlew test\n/bin/bash: ./gradlew: No such file or directory\n",
            encoding="utf-8",
        )
        return VerifyRunResult(
            commands=list(commands),
            command_results=[
                VerifyCommandResult(
                    command="./gradlew test",
                    exit_code=127,
                    output="/bin/bash: ./gradlew: No such file or directory\n",
                    stderr="/bin/bash: ./gradlew: No such file or directory\n",
                    real_execution=False,
                    non_execution_reason="execution_layer_failure",
                )
            ],
            artifact_path=artifact_path,
            failure_category="infra_unavailable",
        )

    monkeypatch.setattr(agent_loop_mod, "run_task_verification", fake_run_task_verification)

    cfg = AppConfig(
        model="test-model",
        routing_mode="code_only",
        verify_commands=["./gradlew test"],
    )
    sessions_dir = tmp_path / "sessions"
    session = create_session(
        cfg=cfg,
        root=tmp_path,
        mode="auto",
        yes=True,
        max_steps=6,
        no_log=False,
        api_key_override="override-key",
        one_shot_execution=True,
        session_log_dir_override=sessions_dir,
        session_id_override="one-shot-infra-blocker-finalizes",
    )
    session.client = _ScriptedClient(
        [
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc1",
                        name="fs_write",
                        arguments={"path": "src/app.py", "content": "print('changed')\n"},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content="",
                tool_calls=[ToolCall(id="tc2", name="verify_run", arguments={})],
                raw={},
            ),
            LLMResponse(
                content=(
                    "I am blocked because `./gradlew` is missing, so the configured "
                    "verification command cannot run."
                ),
                tool_calls=[],
                raw={},
            ),
        ]
    )  # type: ignore[assignment]

    try:
        exit_code = session.run_turn("Implement the requested code change.")
    finally:
        session.close()

    assert exit_code == 0
    events = list(read_session_events(sessions_dir / "one-shot-infra-blocker-finalizes.jsonl"))
    assert not [event for event in events if event.get("type") == "one_shot_completion_gate_failed"]


