def test_one_shot_completion_gate_failed_verification_accepts_after_checklist(
    tmp_path: Path,
) -> None:
    cfg = AppConfig(model="test-model", routing_mode="code_only")
    sessions_dir = tmp_path / "sessions"
    surface = _RecordingSurface()
    session = create_session(
        cfg=cfg,
        root=tmp_path,
        mode="auto",
        yes=True,
        max_steps=12,
        no_log=False,
        api_key_override="override-key",
        one_shot_execution=True,
        session_log_dir_override=sessions_dir,
        session_id_override="one-shot-verify-repair-terminal",
        surface=surface,
    )
    latest_final_text = "Implemented the repair attempt; verification is still failing."
    client = _ScriptedClient(
        [
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc1",
                        name="fs_write",
                        arguments={"path": "src/app.py", "content": "print('initial')\n"},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc2",
                        name="verify_run",
                        arguments={"commands": [_VERIFY_NAME_ERROR_COMMAND]},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content=latest_final_text,
                tool_calls=[],
                raw={},
            ),
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc3",
                        name="fs_write",
                        arguments={"path": "src/app.py", "content": "print('repair attempt')\n"},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc4",
                        name="verify_run",
                        arguments={"commands": [_VERIFY_NAME_ERROR_COMMAND]},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content=latest_final_text,
                tool_calls=[],
                raw={},
            ),
            LLMResponse(
                content=latest_final_text,
                tool_calls=[],
                raw={},
            ),
            LLMResponse(
                content=latest_final_text,
                tool_calls=[],
                raw={},
            ),
            LLMResponse(
                content=(
                    "Completed work: retried the failing verification repair path.\n"
                    "Remaining work: verification is still failing and needs another fix.\n"
                    "Known issues or risks: completion-gate repair attempts were exhausted."
                ),
                tool_calls=[],
                raw={},
            ),
        ]
    )
    session.client = client  # type: ignore[assignment]

    try:
        exit_code = session.run_turn("Implement the requested code change.")
    finally:
        session.close()

    assert exit_code == 0
    events = list(read_session_events(sessions_dir / "one-shot-verify-repair-terminal.jsonl"))
    _assert_no_completion_gate_terminal_events(events)
    verify_results = [
        dict((event.get("payload") or {}).get("result") or {})
        for event in events
        if event.get("type") == "tool_result"
        and (event.get("payload") or {}).get("name") == "verify_run"
    ]
    assert verify_results
    assert verify_results[-1].get("all_passed") is False
    assert not surface.errors
    assert not any(event.get("type") == "forced_final_summary_requested" for event in events)
    assert surface.final_messages[-1].startswith(latest_final_text + "\n\nNot verified:")
    # A failed observed check remains visible even if it was not one of the
    # preconfigured required command strings.
    final = next(event["payload"] for event in reversed(events) if event["type"] == "final")
    assert final["verification_notice"] is True
    assert final["task_outcome"]["problems"]
    assert session.last_turn_outcome["verified_success"] is False


