def test_one_shot_docs_only_readme_change_requires_explicit_verification_contract() -> None:
    assert _verification_expected_for_turn(
        turn_intent="execute",
        blocked=False,
        touched_repo_paths={"README.md"},
        verification_contract_requires_execution=True,
    )
    assert _verification_expected_for_turn(
        turn_intent="execute",
        blocked=True,
        touched_repo_paths={"README.md"},
        verification_contract_requires_execution=True,
    )
    assert not _verification_expected_for_turn(
        turn_intent="execute",
        blocked=False,
        touched_repo_paths={"README.md"},
        verification_contract_requires_execution=False,
        effective_verification_commands=["pytest -q"],
    )
    assert not _verification_expected_for_turn(
        turn_intent="execute",
        blocked=False,
        touched_repo_paths={"notes/result.txt"},
        verification_contract_requires_execution=False,
        effective_verification_commands=["pytest -q"],
    )
    assert _verification_expected_for_turn(
        turn_intent="execute",
        blocked=False,
        touched_repo_paths={"src/app.py"},
        verification_contract_requires_execution=False,
        effective_verification_commands=["pytest -q"],
    )
    assert not _verification_expected_for_turn(
        turn_intent="execute",
        blocked=False,
        touched_repo_paths={"styles/site.css"},
        verification_contract_requires_execution=False,
        effective_verification_commands=["pytest -q"],
    )
    assert not _verification_expected_for_turn(
        turn_intent="execute",
        blocked=False,
        touched_repo_paths={"src/app.py"},
        verification_contract_requires_execution=False,
        effective_verification_commands=["npm test"],
    )
    assert _verification_expected_for_turn(
        turn_intent="execute",
        blocked=False,
        touched_repo_paths={"package.json"},
        verification_contract_requires_execution=False,
        effective_verification_commands=["npm test"],
    )


