def test_one_shot_shell_edit_after_verification_invalidates_freshness(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    mutate_cmd = "python3 -c 'rewrite src/app.py'"
    monkeypatch.setattr(
        agent_loop_mod,
        "shell_run",
        _shell_run_with_repo_mutations(
            mutations={mutate_cmd: ("src/app.py", "print('shell changed')\n")}
        ),
    )

    cfg = AppConfig(model="test-model", routing_mode="code_only", verify_commands=["pytest -q"])
    sessions_dir = tmp_path / "sessions"
    session_id = "one-shot-shell-edit-invalidates-verification"
    session = create_session(
        cfg=cfg,
        root=tmp_path,
        mode="auto",
        yes=True,
        max_steps=7,
        no_log=False,
        api_key_override="override-key",
        one_shot_execution=True,
        session_log_dir_override=sessions_dir,
        session_id_override=session_id,
    )
    session.client = _ScriptedClient(
        [
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc1",
                        name="fs_write",
                        arguments={"path": "src/app.py", "content": "print('initial')\n"},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content="",
                tool_calls=[ToolCall(id="tc2", name="shell_run", arguments={"cmd": "pytest -q"})],
                raw={},
            ),
            LLMResponse(
                content="",
                tool_calls=[ToolCall(id="tc3", name="shell_run", arguments={"cmd": mutate_cmd})],
                raw={},
            ),
            LLMResponse(
                content="Implemented the requested code change and ran verification.",
                tool_calls=[],
                raw={},
            ),
            LLMResponse(
                content="Implemented the requested code change and ran verification.",
                tool_calls=[],
                raw={},
            ),
        ]
    )  # type: ignore[assignment]

    try:
        exit_code = session.run_turn("Implement the requested code change.")
    finally:
        session.close()

    assert exit_code == 0
    events = list(read_session_events(sessions_dir / f"{session_id}.jsonl"))
    _assert_no_completion_gate_terminal_events(events)
    invalidations = [
        event.get("payload", {})
        for event in events
        if event.get("type") == "verified_state_invalidated_by_edit"
    ]
    assert invalidations
    invalidation = invalidations[-1]
    assert invalidation.get("tool") == "shell_run"
    assert invalidation.get("requested_tool") == "shell_run"
    assert invalidation.get("tool_call_id") == "tc3"
    assert str(invalidation.get("verified_generation_id", "")).startswith(
        "verification-generation-"
    )
    assert "re-verify before finalizing" in str(invalidation.get("message", ""))


