def test_one_shot_verify_run_non_executing_override_does_not_count(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    verify_commands: list[str],
    override_command: str,
    session_suffix: str,
) -> None:
    monkeypatch.setattr(
        agent_loop_mod,
        "run_task_verification",
        lambda **_kwargs: pytest.fail(
            "verify engine should not run for non-executing verification overrides"
        ),
    )

    cfg = AppConfig(
        model="test-model",
        routing_mode="code_only",
        verify_commands=verify_commands,
    )
    sessions_dir = tmp_path / "sessions"
    session = create_session(
        cfg=cfg,
        root=tmp_path,
        mode="auto",
        yes=True,
        max_steps=6,
        no_log=False,
        api_key_override="override-key",
        one_shot_execution=True,
        session_log_dir_override=sessions_dir,
        session_id_override=f"one-shot-verify-run-non-executing-{session_suffix}",
    )
    session.client = _ScriptedClient(
        [
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc1",
                        name="fs_write",
                        arguments={"path": "src/app.py", "content": "print('ok')\n"},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc2",
                        name="verify_run",
                        arguments={"commands": [override_command]},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content="Implemented the requested code change and ran verification.",
                tool_calls=[],
                raw={},
            ),
            LLMResponse(
                content="Implemented the requested code change and ran verification.",
                tool_calls=[],
                raw={},
            ),
        ]
    )  # type: ignore[assignment]

    try:
        exit_code = session.run_turn("Implement the requested code change.")
    finally:
        session.close()

    assert exit_code == 0
    events = list(
        read_session_events(
            sessions_dir / f"one-shot-verify-run-non-executing-{session_suffix}.jsonl"
        )
    )
    verify_results = [
        dict((event.get("payload") or {}).get("result") or {})
        for event in events
        if event.get("type") == "tool_result"
        and (event.get("payload") or {}).get("name") == "verify_run"
    ]
    assert verify_results
    assert verify_results[-1].get("verification_evidence_allowed") is False
    assert "non_assertive_verification_mode" in str(verify_results[-1].get("error") or "")


