    sessions_dir = tmp_path / "sessions"
    session = create_session(
        cfg=cfg,
        root=tmp_path,
        mode="auto",
        yes=True,
        max_steps=13,
        no_log=False,
        api_key_override="override-key",
        one_shot_execution=True,
        subagents_enabled=True,
        session_log_dir_override=sessions_dir,
        session_id_override="one-shot-post-explore-path-anchors",
    )
    _install_stub_subagent_run(
        session,
        result_text=(
            "Targets now: src/mini_notes/logic.py, src/mini_notes/cli.py, tests/test_logic.py, README.md."
        ),
    )
    session.client = _ScriptedClient(
        [
            _failed_edit_response(),
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc1",
                        name="subagent_run",
                        arguments={"name": "explorer", "task": "Map repo"},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc2",
                        name="fs_read",
                        arguments={"path": "src/mini_notes/logic.py"},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc3",
                        name="fs_read",
                        arguments={"path": "src/mini_notes/logic.py"},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc4",
                        name="fs_read",
                        arguments={"path": "src/mini_notes/logic.py"},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc5",
                        name="fs_write",
                        arguments={"path": "src/mini_notes/logic.py", "content": "done\n"},
                    )
                ],
                raw={},
            ),
            LLMResponse(
                content="",
                tool_calls=[
                    ToolCall(
                        id="tc6",
                        name="verify_run",
                        arguments={"commands": [_VERIFY_OK_COMMAND]},
                    )
                ],
                raw={},
            ),
            # This run edits src/mini_notes/logic.py but verifies with
            # `pytest tests/test_cli.py`, never touching the mirrored
            # tests/test_logic.py — so the blast-radius gate asks for the
            # neighbouring tests before it lets the run finalize. The extra
            # prose replies carry the run through those bounded rounds; this
            # test checks that findings survive scoped recovery and no false bootstrap is emitted.
            LLMResponse(
                content="Implemented search, updated README, and ran tests.",
                tool_calls=[],
                raw={},
            ),
            LLMResponse(
                content="Implemented search, updated README, and ran tests.",
                tool_calls=[],
                raw={},
            ),
            LLMResponse(
                content="Implemented search, updated README, and ran tests.",
                tool_calls=[],
                raw={},
            ),
        ]
    )  # type: ignore[assignment]

    try:
        exit_code = session.run_turn("Implement search command and update tests.")
    finally:
        session.close()

    assert exit_code == 0
    events = list(read_session_events(sessions_dir / "one-shot-post-explore-path-anchors.jsonl"))
    assert not any(event.get("type") == "implementation_bootstrap_nudge" for event in events)
    reports = [
        str(((event.get("payload") or {}).get("result") or {}).get("result") or "")
        for event in events
        if event.get("type") == "tool_result"
        and (event.get("payload") or {}).get("name") == "subagent_run"
    ]
    assert any(
        "src/mini_notes/logic.py" in report and "src/mini_notes/cli.py" in report
        for report in reports
    )
    assert (tmp_path / "src/mini_notes/logic.py").read_text(encoding="utf-8") == "done\n"
    assert any(
        event.get("type") == "tool_result"
        and (event.get("payload") or {}).get("name") == "verify_run"
        for event in events
    )


